using System;using System.Text;using UnityEngine;using LWS.TruckSports;using LWS.TruckBowling;using LWS.TruckSumo;
namespace LWS.TruckLogRolling {
public enum LogStage{Countdown,Balance,Splash,Replay,RoundResult}
public sealed class LogMatch:SportsEventSession {
 public override bool CompactBroadcastStatus=>true;
 public override bool BroadcastStatusVisible=>!string.IsNullOrEmpty(Status);
 public override bool BroadcastParticipantActive(int slot)=>rules.alive[slot];
 public override void DescribeBroadcast(SportsBroadcastAction a,SportsBroadcastFraming f){a.Objective(log.position,2);a.reason="FLOATING LOG / LIVE BALANCE CONTEST";}
 public LogFighter[] fighters;public Rigidbody log;public SportsFloatingBody buoyancy;public SportsEventCamera broadcast;public SportsCameraFit fit;public SportsMotionReplay replay;public SumoRules rules=new SumoRules();public LogStage Stage{get;private set;}public float Clock{get;private set;}public float Timer{get;private set;}public int ContactCount{get;set;}public int Draws{get;private set;}public int Falls{get;private set;}public float MaximumRoll{get;private set;}
 readonly Vector2[] ai=new Vector2[4];readonly float[] think=new float[4],stuck=new float[4],back=new float[4];readonly bool[] brace=new bool[4];readonly StringBuilder text=new StringBuilder(600);string notice="";bool skip;bool pendingAppearanceRecord;readonly int[] appearanceRevisions={-1,-1,-1,-1};
 public override string Title=>"TRUCK LOG ROLLING";public override int MinimumPlayers=>2;public override int MaximumPlayers=>4;public override int OptionCount=>1;public override int WeatherCount=>1;public override string OptionLabel=>"FIRST TO FIVE · SOLO VS AI OR LOCAL";public override bool ReplayControls=>Stage==LogStage.Replay;
 public override string Help=>"BALANCE ON A REAL FLOATING LOG\nTwo to four trucks, first to five round wins. One human can practise against AI; any human/AI mixture and fully autonomous matches are supported. Drive, steer, brake before reversing, reposition your weight and physically bump opponents.\n\nFresh ACTION braces for0.85seconds, lowering your center of mass and applying real wheel braking; then2.6seconds cooldown. It cannot rescue a truck already in the water. NWH wheels and PhysX contacts determine movement; the owned Floating Entities solver supplies the log's buoyancy. Realistic mass scaling applies uniformly to the trucks' wheels/suspension/torque in this mode. No invisible balancing platform or extra collision impulse.\n\nA genuine chassis fall into the water eliminates; minor wheel overhang alone never does. The final survivor wins. Batch all falls from one physics step: simultaneous final falls draw and replay. From35seconds waves build gradually; a120second unresolved heat is an explicit draw and replay. Starts rotate each round. Recorded actual log/truck motion offers angles, slow/fast, rewind and skip. Pause/reconnect preserves current bodies, round and score. Shared settings and rematch configuration apply. Offline only.";
 public override string Header=>Title+" · ROUND "+rules.Heat+" · "+(Stage==LogStage.Countdown?Mathf.CeilToInt(Timer).ToString():Stage==LogStage.Balance?Clock.ToString("F0")+"s":Stage.ToString().ToUpperInvariant());
 public override string Status=>Stage==LogStage.Countdown?"READY · "+Mathf.CeilToInt(Timer):Stage==LogStage.Balance?(Clock>=35?"RAPIDS BUILDING":""):Stage==LogStage.Replay?"REPLAY · "+replay.Speed.ToString("0.##")+"× · CAMERA "+(replay.Angle+1):notice;
 public override string Standings{get{text.Clear();for(int i=0;i<setup.count;i++)text.Append(setup.players[i].name).Append("  ").Append(rules.wins[i]).Append(" / 5 · ").Append(!rules.alive[i]?"IN THE WATER":fighters[i].Brace>0?"BRACED":fighters[i].Cooldown>0?"BRACE "+fighters[i].Cooldown.ToString("F1")+"s":"BRACE READY").Append('\n');return text.ToString();}}
 public int ResultPlace(int slot)=>SportsResultPlacings.FromFinalTotals(slot,setup.count,rules.wins,rules.Winner);
 public override string Results=>(rules.Winner>=0?setup.players[rules.Winner].name+" WINS THE LOG":"COMPLETE")+"\n\n"+Standings+"\nDrawn rounds: "+Draws;
 public override bool TryReadScoreCard(int card,out string value,out string detail){if(card<0||card>=setup.count){value=detail=null;return false;}value=rules.wins[card].ToString();detail="/ 5 · "+(!rules.alive[card]?"IN WATER":fighters[card].Brace>0?"BRACED":fighters[card].Cooldown>0?"BRACE "+fighters[card].Cooldown.ToString("F1")+"s":"READY");return true;}
 protected override void BeginGame(){rules.Reset(setup.count);ContactCount=Draws=Falls=0;MaximumRoll=0;replay.Colorize(new[]{setup.players[0].color,setup.players[1].color,setup.players[2].color,setup.players[3].color,Color.white});BeginHeat();}
 void BeginHeat(){replay.End();Clock=0;Timer=3;Stage=LogStage.Countdown;skip=false;notice="FIND YOUR BALANCE";log.gameObject.SetActive(true);log.isKinematic=false;log.position=new Vector3(0,-.4f,0);log.rotation=Quaternion.identity;log.transform.SetPositionAndRotation(log.position,log.rotation);log.linearVelocity=log.angularVelocity=Vector3.zero;log.WakeUp();buoyancy.Clock=rules.Heat*1.37f;buoyancy.waveAmplitude=.035f;for(int i=0;i<4;i++){fighters[i].gameObject.SetActive(i<setup.count);if(i>=setup.count)continue;int place=(i+rules.Heat-1)%setup.count;float z=(place-(setup.count-1)*.5f)*(setup.count==2?5:3.8f);float x=0;fighters[i].ResetFighter(new Vector3(x,3.0f,z),Quaternion.LookRotation(z<0?Vector3.forward:Vector3.back));think[i]=stuck[i]=back[i]=0;ai[i]=Vector2.zero;brace[i]=false;}pendingAppearanceRecord=Array.Exists(fighters,f=>f.truck.appearanceHost!=null);if(pendingAppearanceRecord)replay.ResetFreshAppearanceRecord();else replay.ResetRecord();Gate();}
 protected override void Simulate(float dt){if(Stage==LogStage.Countdown){buoyancy.Clock+=dt;Timer-=dt;if(Timer<=0){for(int i=0;i<setup.count;i++){fighters[i].truck.body.isKinematic=false;fighters[i].truck.Power(true);}Stage=LogStage.Balance;}return;}if(Stage==LogStage.Balance){Clock+=dt;buoyancy.Clock+=dt;buoyancy.waveAmplitude=.035f+Mathf.Clamp01((Clock-35)/55)*.2f;MaximumRoll=Mathf.Max(MaximumRoll,Mathf.Abs(Mathf.DeltaAngle(0,log.rotation.eulerAngles.z)));for(int i=0;i<setup.count;i++)if(rules.alive[i]&&fighters[i].ObserveWater(dt)){rules.Crossed(i);fighters[i].Fall();Falls++;}if(rules.FinishStep()){Resolve();return;}if(Clock>=120){rules.TimeoutDraw();Resolve();return;}for(int i=0;i<setup.count;i++)if(rules.alive[i]){var drive=commands[i];bool action=actions[i];if(setup.players[i].source==BowlingSource.AI){Bot(i,dt);drive=ai[i];action=brace[i];}fighters[i].Step(drive,action,dt);}CaptureAppearanceReplay();return;}
 if(Stage==LogStage.Splash){Clock+=dt;Timer-=dt;CaptureAppearanceReplay();if(Timer<=0){foreach(var f in fighters){f.Freeze();f.gameObject.SetActive(false);}log.isKinematic=true;log.gameObject.SetActive(false);Stage=LogStage.Replay;replay.Begin(Mathf.Max(0,Clock-6));}return;}
 if(Stage==LogStage.Replay){if(skip||replay.Step(dt)){replay.End();Stage=LogStage.RoundResult;Timer=1.2f;}return;}Timer-=dt;if(Timer<=0){if(rules.Complete)EndMatch();else{rules.NextHeat();BeginHeat();}}}
 void Resolve(){if(rules.HeatWinner>=0)ConfirmScore("heat:"+rules.Heat,rules.HeatWinner,1,rules.wins[rules.HeatWinner],"HOLDS THE LOG",rules.Winner>=0?SportsScoreTier.MatchChampion:SportsScoreTier.RoundWinner,"WIN",null,true,rules.Winner>=0);if(rules.HeatWinner<0){Draws++;notice=Clock>=120?"TIME LIMIT · DRAW / REPLAY":"SAME-STEP FINAL FALLS · DRAW";}else notice=setup.players[rules.HeatWinner].name+" HOLDS THE LOG";for(int i=0;i<setup.count;i++){fighters[i].truck.Power(false);if(rules.alive[i])fighters[i].truck.body.isKinematic=true;}log.isKinematic=true;Stage=LogStage.Splash;Timer=1;feedback.Play(5,0,true);}

 void CaptureAppearanceReplay(){if(pendingAppearanceRecord){bool changed=false;for(int i=0;i<4;i++){var host=fighters[i].truck.appearanceHost;changed|=(host!=null?host.AppearanceRevision:0)!=appearanceRevisions[i];}if(!replay.RefreshAppearanceSources(new[]{0,1,2,3},changed)&&!replay.RefreshAppearanceSources(new[]{0,1,2,3},true))throw new InvalidOperationException("Log appearance refresh requires stopped original truck replay sources.");for(int i=0;i<4;i++){var host=fighters[i].truck.appearanceHost;appearanceRevisions[i]=host!=null?host.AppearanceRevision:0;}pendingAppearanceRecord=false;replay.ResetRecord();}replay.Record(Clock,((1<<setup.count)-1)|(1<<4));}
 void Bot(int slot,float dt){brace[slot]=false;think[slot]-=dt;if(think[slot]>0)return;float skill=(int)setup.players[slot].difficulty;think[slot]=Mathf.Lerp(.25f,.08f,skill*.5f);var truck=fighters[slot].truck;var p=truck.body.worldCenterOfMass;var axis=Vector3.ProjectOnPlane(log.rotation*Vector3.forward,Vector3.up).normalized;if(axis.sqrMagnitude<.1f)axis=Vector3.forward;var side=Vector3.Cross(Vector3.up,axis).normalized;float lateral=Vector3.Dot(p-log.position,side),along=Vector3.Dot(p-log.position,axis);Vector3 target=log.position+axis*Mathf.Clamp(along,-7.5f,7.5f);bool danger=Mathf.Abs(lateral)>1.35f||Mathf.Abs(along)>9;float nearest=float.MaxValue;if(!danger)for(int i=0;i<setup.count;i++)if(i!=slot&&rules.alive[i]){var q=fighters[i].truck.body.worldCenterOfMass;float d=(q-p).sqrMagnitude;if(d<nearest){nearest=d;target=Vector3.Lerp(q,log.position+axis*Mathf.Clamp(Vector3.Dot(q-log.position,axis),-7,7),.35f);}}target.y=p.y;var direction=target-p;float angle=Vector3.SignedAngle(Vector3.ProjectOnPlane(truck.transform.forward,Vector3.up),direction,Vector3.up);float steering=Mathf.Clamp(angle/32,-1,1),throttle=Mathf.Abs(angle)>110?-.65f:danger?.5f:Mathf.Abs(angle)>55?.45f:1;if(throttle<0)steering=-steering;stuck[slot]=truck.body.linearVelocity.magnitude<.3f?stuck[slot]+think[slot]:0;if(stuck[slot]>1.7f){back[slot]=.7f;stuck[slot]=0;}back[slot]=Mathf.Max(0,back[slot]-think[slot]);if(back[slot]>0){throttle=-.65f;steering=slot%2==0?.7f:-.7f;}float error=Mathf.Sin(Clock*(.9f+slot*.1f)+slot*11+rules.Heat)*Mathf.Lerp(.2f,.04f,skill*.5f);ai[slot]=new Vector2(Mathf.Clamp(steering+error,-1,1),throttle);brace[slot]=fighters[slot].Cooldown<=0&&(danger||log.angularVelocity.magnitude>.65f)&&Mathf.Sin(Clock*2+slot*7+rules.Heat)>(skill==0?.3f:skill==1?-.2f:-.7f);}
 public override void ExtraAction(string key){if(Stage!=LogStage.Replay)return;if(key=="replayangle")replay.Angle=(replay.Angle+1)%3;else if(key=="replayspeed")replay.Speed=replay.Speed==1?.5f:replay.Speed==.5f?2:1;else if(key=="replayrewind")replay.Seek(Mathf.Max(0,replay.Cursor-3));else if(key=="replayskip")skip=true;ConsumeActions();}
 protected override void Present(float dt){if(broadcast==null)return;Vector3 focus=Stage==LogStage.Replay?replay.Position(4):log.position;var offset=Stage==LogStage.Replay&&replay.Angle==1?new Vector3(-16,9,-13):Stage==LogStage.Replay&&replay.Angle==2?new Vector3(5,20,16):new Vector3(15,15,-24);broadcast.Pose(focus,offset,58);fit.arenaBounds=new Bounds(focus+Vector3.up*1.5f,new Vector3(17,7,29));fit.Apply();}
 protected override void StopGame(){if(replay!=null)replay.End();if(log!=null)log.isKinematic=true;if(fighters!=null)foreach(var f in fighters)if(f!=null)f.Freeze();}protected override void StopSounds(){if(fighters!=null)foreach(var f in fighters)if(f!=null){f.truck.StopSound();if(f.scrape!=null)f.scrape.Stop();}}
}
}
